      "documento": "pdq-nci-hcl-es",
      "fragmentos": [0],
      "seccion": "_13"
    },
    {
      "cita_literal_breve": "La decisión de tratar se fundamenta en los siguientes signos de progresión de la\nenfermedad:",
      "documento": "pdq-nci-hcl-es",
      "fragmentos": [0],
      "seccion": "_13"
    }
  ],
  "fundamentos_verificables": [
